// Lazy TeamStore singleton — used by all recall paths to build access_context
let _teamStoreCache = null;
let _teamStoreHooked = false;
async function getTeamStore() {
  if (!prisma) return null;
  if (_teamStoreCache) return _teamStoreCache;
  const mod = await import('./teams/team-store.js');
  _teamStoreCache = new mod.TeamStore(prisma);
  if (!_teamStoreHooked && typeof _teamStoreCache.onMembershipChange === 'function') {
    _teamStoreCache.onMembershipChange((userId, orgId) => {
      invalidateAccessContextCache(userId, orgId);
    });
    _teamStoreHooked = true;
  }
  return _teamStoreCache;
}

// Cached per-request access context: { projectIds, teamIds }
// Cache TTL 60s to avoid hitting DB on every recall in tight loops.
const _accessContextCache = new Map();
// Recently-active tenants, so the recall keep-warm probe hits REAL orgs (keeping
// their Qdrant collection + connection + collectionReady cache hot) instead of a
// fixed dummy org. Keyed by orgId; holds a representative user + projectIds +
// lastSeen. Pruned by the keep-warm sweep to a recent window.
const _activeOrgs = new Map();
function _recordActiveOrg(userId, orgId, value) {
  if (!userId || !orgId) return;
  _activeOrgs.set(orgId, {
    userId,
    projectIds: Array.isArray(value?.projectIds) ? value.projectIds.slice(0, 1) : [],
    lastSeen: Date.now(),
  });
}
async function buildAccessContext(userId, orgId) {
  if (!userId || !orgId) return null;
  const key = `${userId}:${orgId}`;
  const cached = _accessContextCache.get(key);
  const now = Date.now();
  if (cached && cached.expiresAt > now) { _recordActiveOrg(userId, orgId, cached.value); return cached.value; }
  const ts = await getTeamStore();
  if (!ts) return null;
  try {
    const { crossProjectEnabledForOrg } = await import('./resident/cognition-pilot.js');
    const [projectIds, teamIds, membership, crossProject] = await Promise.all([
      ts.accessibleProjectIds({ userId, orgId }),
      ts.accessibleTeamIds({ userId, orgId }),
      prisma.userOrganization.findUnique({
        where: { userId_orgId: { userId, orgId } },
        select: { role: true },
      }).catch(() => null),
      crossProjectEnabledForOrg(prisma, orgId).catch(() => true), // fail-open: don't over-filter on a lookup error
    ]);
    // Hierarchy: org owners/admins sit above the project layer — their access
    // context spans EVERY active project in the org, so admin MCP tokens and
    // recall see cross-project without explicit membership rows.
    const orgRole = membership?.role || null;
    let effectiveProjectIds = projectIds;
    if (orgRole === 'owner' || orgRole === 'admin') {
      const all = await prisma.project.findMany({
        where: { orgId, status: 'active' },
        select: { id: true },
      }).catch(() => []);
      effectiveProjectIds = Array.from(new Set([...projectIds, ...all.map(p => p.id)]));
    } else if (orgRole === 'guest') {
      // SECURITY (tenant isolation): guests are project-scoped external invitees
      // and must be locked to the projects they were EXPLICITLY added to. The
      // default accessibleProjectIds union also grants projects inherited via
      // team membership — but every project is auto-linked to the org's
      // "all-members"/Default Team, and guests sit on it, so the team lane would
      // otherwise hand a guest the ENTIRE org (the cross-project recall leak).
      // Restrict guests to explicit projectMember rows only.
      const explicit = await prisma.projectMember.findMany({
        where: { userId, project: { orgId, status: 'active' } },
        select: { projectId: true },
      }).catch(() => []);
      effectiveProjectIds = explicit.map(p => p.projectId);
    }
    const value = { projectIds: effectiveProjectIds, teamIds, orgRole, crossProject: crossProject !== false };
    _accessContextCache.set(key, { value, expiresAt: now + 60_000 });
    _recordActiveOrg(userId, orgId, value);
    return value;
  } catch (err) {
    console.warn('[access-context] build failed:', err.message);
    return null;
  }
}

/**
 * Invalidate cached access context for a user.
 * Call after membership changes (team join/leave, project add/remove).
 */
export function invalidateAccessContextCache(userId, orgId) {
  if (!userId) return;
  const key = orgId ? `${userId}:${orgId}` : null;
  if (key) {
    _accessContextCache.delete(key);
  } else {
    for (const k of _accessContextCache.keys()) {
      if (k.startsWith(`${userId}:`)) _accessContextCache.delete(k);
    }
  }
}

